package com.quizrank.backend.controller;
import com.quizrank.backend.entity.Subject;import com.quizrank.backend.repository.SubjectRepository;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/subjects") public class SubjectController {private final SubjectRepository r;public SubjectController(SubjectRepository r){this.r=r;}@GetMapping public List<Subject> all(){return r.findAll();}@GetMapping("/{id}") public Subject one(@PathVariable Integer id){return r.findById(id).orElseThrow(()->new NoSuchElementException("Subject not found"));}@GetMapping("/batch/{batch}") public List<Subject> batch(@PathVariable String batch){return r.findByBatch(batch);}@GetMapping("/teacher/{id}") public List<Subject> teacher(@PathVariable Integer id){return r.findByTeacherId(id);}}
